-- Catalogue steps with no description now say what to do and why. 136 distinct steps, 422 rows. Only steps whose
-- notes are empty are touched, so nothing already written is overwritten; steps with no honest description are left empty.
-- Drafted from the step and its linked catalogue activity, then checked by an independent reviewer for accuracy, claims and style.
DO $$
DECLARE
  expected CONSTANT int := 422;
  changed int;
BEGIN
  WITH d(name, activity_id, notes) AS (VALUES
    ('16:8 Fasting Window', 'fasting_16_8', 'Fast for 16 hours, sleep included, then eat all your meals inside an 8-hour window, for example noon to 8 pm. Water and unsweetened tea are fine. A fixed window gives eating a simple rhythm; check with your doctor first if unsure.'),
    ('4-7-8 Diaphragmatic Breathing', 'activity_oneill_478_breathing', 'Sit or lie comfortably and breathe low into the belly. Inhale through the nose for 4 counts, hold for 7, exhale slowly through the mouth for 8; repeat for 4 cycles. The long exhale helps your body shift toward rest and wind down for sleep.'),
    ('90/90 Hip Stretch', 'ninety_ninety_hip_stretch', 'Sit on the floor with your front leg bent 90 degrees at the hip and knee and your back leg bent the same way behind you. Sit tall, hinge forward from the hips and breathe slowly for about 30 seconds, then switch sides. Works the hips through inward and outward rotation.'),
    ('Abdominal Crunch Machine', 'activity_gym_machine_abdominal_crunch_machine', 'Adjust the seat and weight so the movement stays smooth. Exhale and curl your ribs toward your hips, leading with the abs rather than the neck or hip flexors, then return slowly. Builds strength in the front of the core.'),
    ('Ab Wheel Rollout', 'activity_strength_ab_wheel_rollout', 'Kneel with the wheel under your shoulders, brace your core and tuck the ribs down. Roll out only as far as your lower back stays steady, then pull back in with control. Builds core strength and shoulder stability.'),
    ('Achilles Stretch', 'activity_stretch_achilles_stretch', 'Step one foot back with the heel down and the back knee slightly bent, then lean gently forward. Breathe out as you ease in, feel a mild pull rather than pain, and hold about 30 seconds per side. Helps keep the ankle and lower calf flexible.'),
    ('Aerobics', 'aerobics', 'Follow the footwork and arm patterns at a steady rhythm, using the low-impact option while you learn the sequence. Keep your space clear and non-slip, and stop if you feel chest pain, faintness or sharp pain. Builds aerobic fitness and coordination.'),
    ('After Action Review (AAR) Journaling', 'activity_protocol_after_action_review_aar_journaling', 'Write a few lines answering what you intended, what actually happened, why the two differed and what you will do next time. Keep it honest and blame-free, and do not edit as you go. Helps you turn what happened into lessons you can use.'),
    ('Afternoon Pool Session', 'activity_protocol_afternoon_pool_session_5000m_pace_work_race_simulation_u', 'Warm up with easy laps, then swim pace sets and race-simulation efforts, aiming for about 5000 m in total. Keep underwater work short, never push your breath hold, and swim where someone can see you. Builds endurance and pace control.'),
    ('American Football', 'american_football', 'Warm up with dynamic movements, then play in short, explosive efforts with recovery between plays. Stay in an athletic stance (knees bent, weight on the balls of your feet), wear protective gear and drink during breaks. Builds conditioning, agility and teamwork.'),
    ('Ankle Circles', 'activity_stretch_ankle_circles', 'Lift one foot and slowly draw big circles with your toes, moving only from the ankle, several times each way before switching feet. Keep it smooth and stop short of pain. Helps keep the ankle moving freely and warms it up.'),
    ('Ankle Work: Toe-Heel & Circles', 'activity_ankle_prep_toe_heel_circles', 'Rock gently onto your toes, then back onto your heels, then draw slow, full circles with each ankle, one direction and then the other. Keep it smooth and pain-free. Helps keep your ankles mobile for walking and balance.'),
    ('Archery', 'archery', 'Set a steady stance side-on to the target, then repeat the same smooth shot sequence each time: draw, anchor, aim, release. Keep your breathing calm and follow range safety rules. Trains focus, control and upper-body steadiness.'),
    ('Arm Circles Warmup', 'activity_stretch_arm_circles_warmup', 'Stand tall with your arms out to the sides and trace slow, large circles, then reverse direction. Keep your shoulders relaxed and the motion smooth, never forced. Warms up the shoulders before upper-body work.'),
    ('Arnold Press', 'activity_strength_arnold_press', 'Start with dumbbells in front of your shoulders, palms facing you, then rotate your palms forward as you press overhead. Brace your core and reverse the rotation as you lower with control. Builds shoulder strength through a rotating press.'),
    ('Assault Bike', 'activity_assault_bike', 'Pedal and push-pull the handles together at a steady, moderate effort where you can still talk, keeping your breathing even. Builds your aerobic base and endurance.'),
    ('Assisted Pull-Up Machine', 'activity_assisted_pull_up_machine', 'Set the counterweight, grip the bar overhand and pull your elbows down until your chin clears the bar, then lower slowly to full arm extension. Builds back and arm pulling strength; reduce the assistance as you get stronger.'),
    ('Back Extension', 'activity_back_extension', 'Set the pad against your hips with your feet anchored, hinge forward with control, then lift until your body forms one straight line. Do not over-arch at the top. Strengthens the lower back, glutes and hamstrings.'),
    ('Back Extension Machine', 'activity_gym_machine_back_extension_machine', 'Adjust the machine so the pivot lines up with your hips and start with a light load. Keep your spine long, extend back only until it is straight, then return slowly. Builds the lower back, glutes and hamstrings.'),
    ('Back Lever', 'activity_back_lever', 'Advanced hold. From an inverted hang on a bar or rings, lower your body with straight arms until you are flat and face-down, hold, then return with control. Build up through tuck progressions first. Trains straight-arm strength and body control.'),
    ('Badminton', 'badminton', 'Warm up first, then rally with small, quick shuffle steps, getting under the shuttle for high, deep clears and mixing in the odd smash. Hold the racquet loosely, like a handshake. Builds agility, reflexes and aerobic fitness.'),
    ('Barbell Back Squat', 'activity_barbell_back_squat', 'Unrack the bar across your upper back, brace your core and keep your chest up. Descend under control to about parallel with knees tracking over your toes, then drive up through your whole foot. Use a rack with safety arms for heavy sets. Builds leg and hip strength.'),
    ('Barbell Bench Press', 'activity_barbell_bench_press', 'Lie back with feet planted and shoulder blades pulled together, lower the bar to your chest with control, then press it up. Use a spotter or safety arms for heavy sets. Builds chest, front shoulder and triceps strength.'),
    ('Barbell Curl', 'activity_barbell_curl', 'Stand tall with elbows fixed at your sides, curl the bar up without swinging, then lower it slowly. Builds strength in the biceps and forearms.'),
    ('Barbell Deadlift', 'activity_barbell_deadlift', 'Keep a neutral spine, brace your core and lats, then push the floor away and stand tall with the bar close to your legs. Builds full-body strength through the hips, back and grip.'),
    ('Barbell Decline Bench Press', 'activity_barbell_decline_bench_press', 'Secure your feet under the pads, set your shoulder blades back and lower the bar under control to the lower chest, then press up. Trains the lower chest and triceps; use a spotter.'),
    ('Barbell Front Squat', 'activity_barbell_front_squat', 'Rack the bar across the front of your shoulders, keep elbows high and chest up, and squat down with your core braced. Builds quad and core strength and trains an upright posture.'),
    ('Barbell Incline Bench Press', 'activity_barbell_incline_bench_press', 'Plant your feet, pull your shoulder blades back, lower the bar to the upper chest with control and press up. Builds the upper chest, front shoulders and triceps.'),
    ('Barbell Overhead Press', 'activity_barbell_overhead_press', 'Brace your core and glutes, press the bar up in a straight line past your face, and finish with it stacked over your shoulders. Builds shoulder and triceps strength and trunk stability.'),
    ('Barbell Overhead Squat', 'activity_barbell_overhead_squat', 'Lock the bar out overhead with strong arms, keep your chest up and core braced, and squat only as deep as you can hold that position. Trains mobility, shoulder stability and coordination.'),
    ('Barbell Pendlay Row', 'activity_barbell_pendlay_row', 'Hinge with a flat back, row the bar from the floor to your lower chest and squeeze the shoulder blades, then return it to the floor each rep. Builds upper-back and lat strength.'),
    ('Barbell Push Press', 'activity_barbell_push_press', 'Dip slightly through the knees, drive up with your legs and press the bar overhead in a straight line, then lower it with control. Builds shoulder strength and teaches full-body power.'),
    ('Barbell Reverse Curl', 'activity_strength_barbell_reverse_curl', 'Hold the bar with an overhand grip, elbows fixed at your sides and wrists straight, and curl it up smoothly, then lower slowly. Builds forearm and grip strength and the muscles that bend the elbow.'),
    ('Barbell Romanian Deadlift', 'activity_barbell_romanian_deadlift', 'Soften your knees, push the hips back and slide the bar down your thighs with a flat back until you feel a hamstring stretch, then drive the hips forward. Trains the hamstrings and glutes.'),
    ('Barbell Row', 'barbell_row', 'Hinge at the hips with a flat back, pull the bar toward your lower chest and squeeze your shoulder blades together, then lower with control. Builds back and arm strength.'),
    ('Barbell Skull Crusher', 'activity_barbell_skull_crusher', 'Lie on a bench with the bar over your chest and upper arms still. Bend only at the elbows to lower the bar toward your forehead, then press back up; keep the weight light enough to control for 8 to 12 smooth reps. Builds triceps strength.'),
    ('Barbell Sumo Deadlift', 'activity_barbell_sumo_deadlift', 'Stand wide with toes angled out, grip the bar inside your knees and keep your chest up. Brace, push the floor apart to stand tall, then lower with control. Builds strength through the legs, hips and back.'),
    ('Barbell Trap Bar Deadlift', 'activity_barbell_trap_bar_deadlift', 'Stand inside the bar with feet hip-width, hold the neutral handles, chest up and spine long. Brace, push through the floor to stand tall, then lower with control. Builds leg, hip and back strength with a centred load.'),
    ('Barbell Upright Row', 'activity_strength_barbell_upright_row', 'Stand tall with the bar at your thighs, hands about shoulder-width. Lead with your elbows and pull the bar close to your body to lower-chest height, elbows no higher than your shoulders, then lower slowly. Builds shoulders and upper back; ease off if your shoulders pinch.'),
    ('Barre', 'barre', 'Stand tall at the barre, ribs stacked over hips, and work in small, controlled pulses and holds while breathing steadily. Keep the core drawn in. Builds muscular endurance, posture and core strength.'),
    ('Baseball', 'baseball', 'Warm up the arms and shoulders first, then work through throwing, batting and fielding at a comfortable effort, staying loose through each swing and throw. Builds hand-eye coordination and rotational power.'),
    ('Basketball', 'basketball', 'Warm up, then play or practise in short bursts: stay low on defence, dribble with both hands, and take breaks when you need them. Supports cardio fitness, agility and hand-eye coordination.'),
    ('Battle Ropes', 'activity_battle_ropes', 'Stand in a soft athletic stance, core braced, and make alternating waves with the ropes in short bursts, resting between rounds. Keep your breathing steady. Builds arm and shoulder endurance and gets the heart rate up.'),
    ('Bear Crawl', 'activity_bear_crawl', 'Hands under shoulders, knees hovering just off the floor, back flat and core tight. Step opposite hand and foot forward in small, controlled steps for 30 to 45 seconds. Builds full-body strength and body control.'),
    ('Beginner Yoga', 'activity_yoga_beginner', 'Flow through cat-cow with your breath, then settle into cobbler, tree on each side and cobra, breathing slowly in each. Ease into every shape and never force it. Supports mobility, balance and body awareness.'),
    ('Bicycle Crunch', 'activity_strength_bicycle_crunch', 'Lie on your back, hands lightly behind your head, lower back pressed down. Bring one elbow toward the opposite knee as the other leg extends, rotating through the ribs and not pulling on your neck. Trains the abs and obliques.'),
    ('Bike Session', 'activity_protocol_bike_session_60k_at_race_pace_aero_position', 'Ride 60 km at a steady race pace in the aero position on a safe, traffic-free route or trainer, shoulders relaxed. Hold an effort you can sustain and ease off if your form fades. Builds cycling-specific endurance and the ability to hold power in race posture.'),
    ('Bouldering', 'bouldering', 'Climb short problems over padded flooring: plan each move, keep the landing zone clear, and down-climb or drop with soft knees. Builds grip and pulling strength, with short bursts of cardio effort between rests.'),
    ('Boxing', 'boxing', 'Wrap your hands first, then keep them up, pivot on the balls of your feet and breathe out sharply with each jab or cross, working in 3-minute rounds with 1 minute of rest. Builds cardio fitness, coordination and upper-body power.'),
    ('Bradford Press', 'activity_strength_bradford_press', 'Using a light bar, press up from the front of the shoulders, lower it behind the head, press up again, then lower to the front, core braced and spine neutral. Stay within the range your shoulders comfortably allow. Builds shoulder strength and endurance.'),
    ('Brain Exercises', 'activity_protocol_brain_exercises_brainhq_cognitive_training', 'Spend this time on a focused brain-training session, such as BrainHQ, somewhere quiet and free of distractions. Regular practice gives your attention, memory and processing speed a workout.'),
    ('Brick Run', 'activity_protocol_brick_run_10k_off_the_bike_negative_split', 'Run 10K straight off the bike, starting with short, quick steps while your legs adjust, then build the pace so the second half is faster. Trains your legs to run well when tired and builds pacing discipline.'),
    ('Brush teeth', 'activity_protocol_thorough_tooth_brushing_flossing_water_flosser', 'Brush every tooth surface gently with the bristles angled toward the gumline, then clean between the teeth with floss or a water flosser. Helps remove plaque and keeps teeth and gums clean.'),
    ('Burpee', 'activity_burpee', 'Squat, hands down, jump the feet back to a solid plank, do a push-up, jump in and finish with an explosive jump, landing softly. Builds full-body strength and endurance; slow down if form slips.'),
    ('Butterfly Stretch', 'activity_butterfly_stretch', 'Sit tall with the soles of your feet together and knees falling out, then lean forward from the hips with a long back. Hold about 30 seconds, breathing slowly, no bouncing. Gently opens the hips and inner thighs.'),
    ('Cable Crossover', 'activity_cable_crossover', 'Set the pulleys high, take a staggered stance and, with soft elbows, sweep the handles down and forward in a controlled arc until they meet in front of you, then return slowly. Builds chest strength and shoulder stability.'),
    ('Cable Crunch', 'activity_gym_machine_cable_crunch', 'Kneel facing the stack, brace, and curl your ribs toward your hips, leading with the abs rather than the neck or hips. Return slowly. Builds core strength with steady resistance.'),
    ('Cable Fly Low-to-High', 'activity_strength_cable_fly_low_to_high', 'With the pulleys low and your core braced, sweep the handles up and together in front of the upper chest in a smooth arc, then lower under control. Builds upper-chest and shoulder strength.'),
    ('Cable Rear Delt Fly', 'activity_gym_machine_cable_rear_delt_fly', 'Hold the handles with soft elbows and sweep your arms out and back in a wide arc, gently squeezing the shoulder blades, then return slowly. Builds the rear shoulders and upper back, which supports good posture.'),
    ('Calf Stretch Wall', 'activity_calf_stretch_wall', 'Hands on a wall, one foot stepped back with the heel down and the back leg fairly straight; lean in until you feel a stretch through the calf. Hold about 30 seconds, breathing slowly and without bouncing, then switch legs. Helps ease calf tightness and supports ankle mobility.'),
    ('Canoeing', 'canoeing', 'Paddle at a steady, relaxed rhythm, sitting or kneeling tall and turning from the torso rather than just the arms. Wear a life jacket and check the weather and water first. Builds upper-body and core endurance.'),
    ('Cardio', 'activity_root_cardio', 'Choose an aerobic activity you enjoy, such as brisk walking, cycling or jogging, and keep a steady effort that raises your heart rate while you can still talk in short sentences. Supports heart health and stamina.'),
    ('Chin-Up', 'activity_chin_up', 'Palms facing you, hands shoulder-width apart; start from a hang with shoulder blades drawn down, pull until your chin clears the bar, then lower slowly with no swinging. Builds pulling strength in the back, arms and grip.'),
    ('Clean and Jerk', 'activity_strength_clean_and_jerk', 'Keep the bar close, drive up through the legs and hips, drop under the bar to catch it at the shoulders, then dip and drive it overhead. Start light and learn the technique with a coach. Builds full-body power and coordination.'),
    ('Close-Grip Bench Press', 'activity_protocol_closegrip_bench_press_4_sets_x_12_reps_elbows_in_tight', 'Lie back with feet planted and shoulder blades pulled together; grip the bar about shoulder-width, keep elbows tucked close, and lower it to your chest with control before pressing up. Use a spotter if you can. Builds triceps, chest and shoulder strength.'),
    ('Cold Plunge', 'cold_plunge', 'Ease into cold water and stay in for about 3 minutes, breathing slowly and staying calm. Get out early if you feel dizzy or unwell, avoid going in alone, and check with a doctor first if you have a heart condition. Helps train calm under stress.'),
    ('Cold Plunge (optional)', 'cold_plunge', 'Optional: ease into cold water for about 3 minutes, breathing slowly and staying calm. Skip it on days it does not feel right, get out early if you feel dizzy or unwell, avoid going in alone, and check with a doctor first if you have a heart condition. Helps train calm under stress.'),
    ('Cool Down 5 min', 'activity_bj_cool_down', 'Slow right down for about 5 minutes: gentle static stretches for the muscles you just worked, held without bouncing, with slow breaths out. Helps bring your breathing and heart rate down and eases muscle tightness.'),
    ('Cool-Down Jog', 'activity_protocol_cooldown_jog_2k_easy', 'Jog easily at a pace where you can talk in full sentences, shoulders loose and breathing steady, then finish with a short walk. Gradually lowers your heart rate and supports recovery after harder work.'),
    ('Cool-Down Swim or Run', 'swimming', 'Finish your session by easing off to a gentle pace, swimming or running, with relaxed shoulders and smooth, steady breathing. Lets your heart rate and breathing settle gradually after harder effort.'),
    ('Daily Walk', 'proto-act-0d7980fe54c6', 'Walk at a comfortable, brisk pace with tall posture and relaxed arms, breathing steadily so you could still hold a conversation. Supports heart health, mood and circulation, and is easy to fit into any day.'),
    ('Dead Bug', 'activity_strength_dead_bug', 'Lie on your back with arms up and knees over hips. Slowly extend the opposite arm and leg while keeping your lower back pressed into the floor, then switch sides. Trains deep core stability and control.'),
    ('Deadlift or Hip Hinge Pattern', 'activity_protocol_deadlift_or_hip_hinge_pattern', 'Brace the core, push the hips back and keep the spine long, with the load close to your legs. Stand tall by driving the hips forward. Builds the glutes, hamstrings and back, and trains the hip-hinge pattern.'),
    ('Dragon Flag', 'activity_dragon_flag', 'Lie on a bench gripping behind your head, then lift your hips and legs until your body is one straight line from shoulders to toes. Lower slowly, stopping before your lower back touches the bench. Bend the knees if needed. Builds core strength and body control.'),
    ('Dryland Swim Strength', 'activity_protocol_dryland_swim_strength_bands_core_shoulder_stability', 'Use resistance bands for slow, controlled pulls and shoulder-stability drills, plus core work, keeping the ribs down and each rep smooth. Builds the strength and shoulder durability that swimming asks for.'),
    ('Dumbbell Rear Delt Fly', 'activity_dumbbell_rear_delt_fly', 'Hinge forward with a flat back, light dumbbells hanging below you, and raise your arms out to the sides with soft elbows, leading with the elbows. Lower slowly. Builds the rear shoulders and upper back.'),
    ('Dumbbell Row', 'activity_dumbbell_row', 'Brace one hand and knee on a bench with a flat back, pull the dumbbell toward your hip, squeeze the shoulder blade back at the top, then lower with control. Builds the lats and upper back, one side at a time.'),
    ('Easy Afternoon Jog', 'activity_protocol_easy_afternoon_jog_8k_shake_legs_out', 'Jog at an easy, conversational pace with relaxed shoulders and steady breathing. Keep it light so your legs loosen up rather than tire. Supports blood flow and active recovery.'),
    ('End Sleep', 'activity_blueprint_wake', 'Get up at your set wake time and let in daylight soon after, by opening the curtains or stepping outside. A steady wake time anchors your body clock and supports energy through the day.'),
    ('Evening hygiene', NULL, 'Wash your face and do your evening skin-care steps in the same order each night. A steady order is easy to keep and marks the end of your day.'),
    ('Evening Pliability', 'activity_protocol_evening_pliability_full_body_winddown', 'Move slowly through gentle full-body stretches, breathing deeply and easing deeper on each exhale. Feel tension, never pain. Helps you unwind and keeps muscles and joints supple.'),
    ('Evening Run or Yoga Session', 'running', 'Pick a run or a yoga session to suit the evening. Run at an easy, conversational pace, tall and relaxed; or flow through yoga slowly with the breath. Either keeps you active, and gentle yoga can help you wind down.'),
    ('Face Pull', 'activity_face_pull', 'Set a rope on a cable at face height and pull it toward your face, elbows high and wide, squeezing the shoulder blades together, then return slowly. Builds the rear shoulders and upper back, which supports posture.'),
    ('Farmer''s Walk', 'activity_farmers_walk', 'Hold a heavy but manageable weight in each hand at your sides, stand tall with shoulders back and ribs over hips, and walk with short, steady steps. Builds grip strength and trunk stability.'),
    ('Fasted Cardio', 'activity_protocol_fasted_cardio_45min_steadystate_beach_run_or_stairmaster', 'Do 45 minutes of steady cardio, such as a run or the stair machine, before you eat, at an even pace where you can still talk. Stop if you feel dizzy or unwell. Builds endurance and supports heart health.'),
    ('Fast Through Afternoon', 'fasting_16_8', 'Keep to your fasting window through the afternoon, sipping water or unsweetened tea, and eat only when your eating window opens. Part of a 16:8 pattern (16 hours fasting, 8 eating) that supports a steady daily eating rhythm. Ease off if you feel faint or unwell.'),
    ('Film Study / Visualization', 'activity_protocol_film_study_visualization', 'Watch a short clip of your sport, then sit comfortably, close your eyes and slowly rehearse the movement in your mind, step by step. Helps sharpen technique and decision-making.'),
    ('Flexibility & Dance', 'activity_protocol_flexibility_dance_balletinspired_hip_mobility', 'Move through slow, ballet-inspired positions that open the hips, keeping the movement smooth and the breath easy, and staying within a comfortable range. Supports hip mobility and balance.'),
    ('Floss teeth', NULL, 'Slide the floss gently between each pair of teeth, curve it around each tooth and move it up and down just under the gum line, using a clean section each time. Helps clear plaque and food a brush can miss.'),
    ('Flutter Kicks', 'activity_strength_flutter_kicks', 'Lie on your back, press your lower back toward the floor and lift both legs a few inches. Kick in small, quick alternating beats with the core braced; stop if your back arches. Builds lower-ab and hip endurance.'),
    ('Foam Rolling', 'foam_rolling', 'Roll slowly over each muscle with your body weight on the roller, pausing briefly on tender spots as you breathe out. Skip joints and the lower back, and ease off if it hurts. Helps ease tightness and supports recovery.'),
    ('Fruit and raw almonds', NULL, 'Take about 10 minutes to eat a piece of fruit with a small handful of raw almonds. Plant-based and in line with the Daniel Fast; the fibre and healthy fats help keep you satisfied between meals.'),
    ('Golden Spiral Breathing Exercise', 'activity_breath_golden_spiral', 'Breathe in for 3 seconds and out for 5, picturing a spiral widening on the inhale and tightening on the exhale. After five rounds, lengthen to 5 in and 8 out, about 8 minutes total. Stop if light-headed; if pregnant or hypertensive, stay at 3 and 5. Helps you settle.'),
    ('Grounding', 'grounding', 'Stand or walk barefoot on grass, sand or soil that is clear of glass and not too hot or cold, letting your attention rest on the feel of the ground and your slow, steady breathing. A simple outdoor pause that can help you feel calmer and present.'),
    ('Hang Clean', 'activity_strength_hang_clean', 'Start with the bar at mid-thigh, hips back, spine long. Drive the hips forward, shrug and pull the elbows high, then drop under the bar and catch it on your shoulders. Use a light weight while you learn the form. Builds explosive hip power and coordination.'),
    ('Hang Power Clean', 'activity_strength_hang_power_clean', 'Hold the bar at your hips with a flat spine and keep it close to the body. Drive the hips through, shrug, and catch the bar on your shoulders with a quick rebend. Builds explosive power through the hips and legs; start light.'),
    ('Heart Rate Zone Tracking', 'activity_protocol_heart_rate_zone_tracking_session', 'Wear a heart-rate monitor and keep your effort inside your target band, for example Zone 2, a pace where you can still talk. Ease off if you drift above it. Steady effort builds your aerobic base and helps you pace training sensibly.'),
    ('Interdental Cleaning', 'activity_interdental_cleaning', 'Slide floss or a correctly sized interdental brush gently between each pair of teeth, hugging the side of each tooth. Use light pressure and do not force it. Cleaning where a toothbrush cannot reach helps keep gums and teeth cleaner.'),
    ('Kettlebell Swing', 'activity_kettlebell_swing', 'Hinge at the hips, let the bell swing back between the legs, then snap the hips forward to float it to chest height. Arms stay loose, spine long. Builds hip and glute power and conditioning.'),
    ('Learning Activity', 'activity_protocol_learning_activity', 'Pick something that absorbs you, such as a puzzle, a building project or a creative game, and give it your full attention without distractions. Mentally engaging play helps keep the mind active and curious.'),
    ('Meal Plan Review', 'activity_protocol_meal_plan_review', 'Once a week, look back over your food log. Notice whether you hit your protein, how much was processed, and any eating tied to mood, then adjust next week. Reviewing helps you stay consistent and makes food choices easier.'),
    ('Meditation', 'meditation', 'Sit comfortably, let your shoulders drop and rest your attention on the natural breath. When the mind wanders, notice it and gently return without judging yourself. Helps calm the body and supports focus and emotional balance.'),
    ('Moisturise', 'activity_kbeauty_moisturizer', 'Smooth a cream or lotion over your skin as the final step, after the watery layers, using gentle upward strokes and pressing it in at the end. It seals in the layers beneath and helps keep your skin barrier hydrated.'),
    ('Morning hygiene', NULL, 'Work through your morning care steps in the same order each day: tongue, teeth, then face and skin. A steady order is easy to keep and starts the day fresh.'),
    ('Morning Intentions & Breathwork', 'activity_dd_intentions', 'Sit comfortably and breathe slowly into the belly for 5 minutes, letting the abdomen rise on each in-breath. Then set your intentions for the day and name something you are grateful for. Starting calm helps set a focused tone.'),
    ('Morning Pool Session', 'activity_protocol_morning_pool_session_6000m_warmup_drills_main_set_kick', 'Swim a structured session: easy warm-up, technique drills, a main set, then a kick set, built around 6000m, so scale the distance to your level. Keep the stroke smooth and breathing relaxed. Builds aerobic endurance with low joint impact.'),
    ('Non-Fiction Reading', 'activity_protocol_nonfiction_reading_biography_science_or_philosophy', 'Settle somewhere quiet with a biography, science or philosophy book and read with your phone out of reach. Pause on an idea that stood out. Reading engages the mind and supports focus and curiosity.'),
    ('Oil Pulling', 'activity_oneill_oil_pulling', 'Swish 1 tablespoon of coconut or sesame oil gently around your mouth for 10 to 20 minutes, then spit it into the bin and never swallow it. A traditional habit that supports a clean, fresh-feeling mouth.'),
    ('Open Water Swim', 'activity_protocol_open_water_swim_2000m_technique_focus', 'Swim 2000 m at an easy, steady pace, lifting your eyes to sight a landmark every so often, rolling your body to breathe and keeping strokes long and smooth. Never swim alone; use a buddy or safety cover. Builds aerobic fitness and open-water confidence.'),
    ('Pliability Touch-Up', 'activity_protocol_pliability_touchup_targeted_areas', 'Spend a few minutes on the areas that feel tight, moving slowly into each position and breathing out as you ease in. Aim for gentle tension, never pain. Supports mobility and helps the body feel looser.'),
    ('Power Clean', 'activity_strength_power_clean', 'Bar over mid-foot, core braced; drive through the legs, extend the hips, and keep the bar close as you catch it on the front shoulders. Use a weight that keeps every rep fast and clean. Builds explosive power and coordination.'),
    ('Power Snatch', 'activity_strength_power_snatch', 'Wide grip, bar close, core braced; drive through the legs and extend the hips explosively, then catch the bar overhead in a partial squat with arms locked. Use a weight that keeps every rep controlled. Builds explosive power, coordination and shoulder stability.'),
    ('Prayer or reflection', NULL, 'Set aside 15 quiet minutes in a calm spot with your phone away. Pray, journal or simply sit and reflect in whatever way is meaningful to you. A pause like this supports calm, perspective and a sense of purpose.'),
    ('Priming Refresh', 'meditation', 'Sit somewhere quiet for 10 minutes. Take slow, deep breaths, bring to mind a few things you are grateful for, then picture how you want the rest of your day to go. A midday reset that supports calm, focus and a steadier mood.'),
    ('Progressive Muscle Relaxation', 'activity_protocol_progressive_muscle_relaxation_tense_and_release_each_body_', 'Working from feet to face, tense one muscle group gently for a few seconds as you breathe in, then release fully as you breathe out and notice the difference. Keep the tension mild, never painful. Helps the body unwind and supports calm.'),
    ('Remove makeup', 'activity_protocol_gentle_micellar_water_cleanse', 'Close your eyes and hold a micellar-water-soaked cotton pad on them for a few seconds, then wipe gently over the face without rubbing hard. Gently lifts makeup, sunscreen and grime so the next steps start on clean skin.'),
    ('Sauna', 'sauna', 'Sit in the heat for 20 minutes, breathing calmly, and drink water before and after. Step out if you feel dizzy or unwell. Supports relaxation, circulation and recovery.'),
    ('Sauna (if available)', 'sauna', 'If a sauna is available, sit in the heat for 20 minutes, breathing calmly, with water before and after. Step out if you feel dizzy or unwell. Supports relaxation, circulation and recovery.'),
    ('Scrape tongue', 'activity_oneill_tongue_scraping', 'Gently scrape the tongue from back to front 5 to 10 times with a clean scraper, rinsing it between strokes. Keep the pressure light. Supports a fresh, clean-feeling mouth as part of your daily hygiene.'),
    ('Spinal Mobility', 'activity_oneill_spinal_mobility', 'Move slowly through cat-cow, side bends, gentle twists and forward folds, breathing easily and staying in a comfortable range. Keeps the spine moving and supports good posture.'),
    ('Start Sleep', 'activity_blueprint_sleep', 'Go to bed at your set time in a cool, dark room, with screens off for about an hour beforehand. A steady bedtime and a calm wind-down help your body settle into sleep.'),
    ('Static Stretch', 'activity_static_stretch', 'Ease slowly into each stretch and hold it for 20 to 30 seconds, breathing deeply and never bouncing. You should feel a gentle pull, not pain. Supports flexibility and helps ease muscle tension.'),
    ('Stop All Eating', 'activity_protocol_stop_all_eating_and_drinking_at_200_pm_stomach_and_duoden', 'Stop all food and drink at 2:00 pm, as this routine directs, so your stomach is empty for the steps that follow. Skip it, or check with your doctor first, if going without food or drink does not suit you.'),
    ('Strength', 'activity_day3_strength_flex', 'Warm up briefly, then work through a controlled bodyweight strength circuit and finish with gentle stretches and slow breathing. Builds strength and supports joint stability and everyday movement.'),
    ('Strength Focus', 'activity_day5_strength', 'After a short warm-up, work through squats, push-ups, lunges and a plank, resting about a minute between sets. Keep your core engaged and drop to your knees for push-ups if needed. Builds strength across the major muscle groups.'),
    ('Strength Session', 'activity_strength_training', 'Do the planned strength work with controlled reps, choosing a weight you can lift with steady form. Brace your core, keep your spine neutral and move through a comfortable full range of motion. Builds strength and supports everyday movement.'),
    ('Stretch 10 minutes', 'stretching', 'Spend 10 minutes stretching the major muscles, holding each stretch 20 to 30 seconds and breathing deeply without bouncing. Feel a gentle pull, never pain. Supports flexibility and helps ease muscle tension.'),
    ('Team Bonding / Journaling', 'activity_protocol_team_bonding_journaling_gratitude_practice', 'Sit down together and write freely without editing, focusing on feelings and what you are grateful for, then share if you wish. Strengthens connection and supports calm, positive reflection.'),
    ('Tongue Scraping', 'activity_oneill_tongue_scraping', 'On waking, before you drink anything, gently scrape from the back of your tongue to the front with a clean scraper, about 5 to 10 strokes. Helps freshen the mouth; stop if it feels uncomfortable.'),
    ('Tooth Brushing', 'activity_protocol_thorough_tooth_brushing_flossing_water_flosser', 'Brush gently but thoroughly, covering every tooth surface and the gumline, then floss and use a water flosser if you have one. Keeps teeth and gums clean and supports everyday oral health.'),
    ('Vision Journaling', 'activity_vision_journaling', 'Find a quiet spot and picture your future self for a couple of minutes, then describe it in your journal in vivid detail and note one to three small actions for today. Write freely, no editing. Supports focus and clarity about what matters to you.'),
    ('Warm Up 10 min', 'activity_bj_warm_up', 'Over 10 minutes, start with easy cardio such as a relaxed walk or gentle cycling, then move into dynamic stretches like leg swings and arm circles. Keep the effort light enough to talk. Warms the body and gets joints and muscles ready for the session.'),
    ('Wash face', 'activity_kbeauty_foam_cleanse', 'Wet your face with lukewarm water, work a gentle foaming or gel cleanser over your skin in small circles, then rinse well and pat dry. Lifts sweat, dirt and leftover residue without stripping your skin, so the next steps start on a clean base.'),
    ('Weighted Sit-Ups', 'activity_protocol_weighted_situps_5_sets_x_25_reps', 'Lie on your back, knees bent, a weight held to your chest. Curl up with control, exhaling as you rise, and lower slowly without pulling on your neck; 5 sets of 25 reps, using a load that keeps form clean. Builds core strength and endurance.'),
    ('Yoga', 'yoga', 'Follow a yoga flow or class that suits your level, moving slowly and matching each movement to an easy breath. Stay in a comfortable range and never force a pose. Supports flexibility, balance and awareness of your body.'),
    ('Zone 2 Cardio', 'activity_root_zone2', 'Choose steady cardio such as brisk walking, cycling or easy jogging and hold a conversational pace for the time shown: you can speak in full sentences, breathing is easy but you feel warm. Builds your aerobic base and endurance.'))
  UPDATE public.protocol_items i
  SET notes = d.notes
  FROM public.protocols p, d
  WHERE p.id = i.protocol_id AND p.user_id IS NULL AND i.kind = 'action' AND NOT coalesce(i.hidden, false)
    AND coalesce(trim(i.notes), '') = '' AND lower(i.display_name) = lower(d.name)
    AND i.catalog_activity_id IS NOT DISTINCT FROM d.activity_id::text;
  GET DIAGNOSTICS changed = ROW_COUNT;
  -- A fill of empty descriptions is harmless whatever the count, so a difference is only logged: another environment may hold more or fewer empty rows.
  IF changed <> expected THEN
    RAISE NOTICE 'step descriptions: changed % rows, expected % (other environments may hold more or fewer empty rows)', changed, expected;
  END IF;
END $$;
